<template>
  <div class="plan-materials" v-loading="loading">
    <nav class="material-categories" role="tablist" aria-label="素材分类"><button v-for="t in types" :key="t.id" role="tab" :aria-selected="type === t.id" :class="{ active: type === t.id }" @click="type = t.id">{{ t.label }}</button></nav>
    <div class="material-toolbar">
      <el-input v-model="searchDraft" placeholder="输入素材名称 / ID，回车搜索" clearable aria-label="搜索投放素材" @keyup.enter="search" @clear="search"><template #suffix><el-button text :icon="Search" aria-label="搜索素材" @click="search" /></template></el-input>
      <el-popover trigger="click" placement="bottom-start" :width="280"><template #reference><el-button :icon="Filter">更多筛选 <el-badge v-if="filterCount" :value="filterCount" /></el-button></template><div class="material-filter-panel"><label>投放状态</label><el-select v-model="status" aria-label="筛选素材投放状态"><el-option label="全部状态" value="" /><el-option v-for="(label, key) in states" :key="key" :value="key" :label="label" /></el-select><label>对应商品</label><el-select v-model="product" clearable placeholder="全部商品" aria-label="筛选素材对应商品"><el-option v-for="p in goods" :key="p.id" :value="p.id" :label="p.name" /></el-select><label>标签</label><el-select v-model="tag" clearable placeholder="全部标签" aria-label="筛选素材标签"><el-option v-for="t in tags" :key="t" :value="t" :label="tagText(t)" /></el-select></div></el-popover>
      <div class="filter-chips"><el-tag v-if="status" closable @close="status = ''">投放状态：{{ states[status] }}</el-tag><el-tag v-if="product" closable @close="product = ''">{{ goods.find(p => p.id === product)?.name }}</el-tag><el-tag v-if="tag" closable @close="tag = ''">{{ tagText(tag) }}</el-tag><el-button v-if="filterCount || keyword" link type="primary" @click="clearFilters">清空</el-button></div>
      <div class="material-tools"><el-tooltip content="导出当前筛选的素材数据"><el-button :icon="Download" aria-label="导出素材数据" :disabled="!filtered.length" @click="download" /></el-tooltip><el-popover trigger="click" placement="bottom-end" :width="250"><template #reference><el-button :icon="Setting" aria-label="设置素材数据列" /></template><strong>展示指标</strong><el-checkbox-group v-model="visibleColumns"><el-checkbox v-for="m in metrics" :key="m.key" :value="m.key">{{ m.label }}</el-checkbox></el-checkbox-group></el-popover></div>
    </div>
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon><el-button text @click="load">重新加载</el-button></el-alert><el-alert v-if="data?.warning" :title="data.warning" type="warning" :closable="false" show-icon />
    <el-table ref="table" :data="paged" row-key="id" class="material-table" scrollbar-always-on :default-sort="{ prop: 'metrics.shows', order: 'descending' }" :empty-text="error ? '素材查询失败，请重新加载' : filteredEmpty" @selection-change="selected = $event" @sort-change="sortChange">
      <el-table-column type="selection" :reserve-selection="true" width="44" />
      <el-table-column :label="categoryLabel" min-width="250"><template #default="{ row }"><div class="material-info"><button v-if="row.type !== 'TITLE'" class="material-cover" :disabled="!canPreview(row)" :aria-label="`预览素材 ${row.id}`" @click="preview = row"><img v-if="row.posterUrl" :src="row.posterUrl" alt="素材缩略图" /><el-icon v-if="row.type === 'VIDEO'" class="cover-play"><VideoPlay /></el-icon><span v-else-if="!row.posterUrl">{{ typeText(row.type) }}</span></button><div class="material-name"><el-tooltip :content="row.name"><strong>{{ row.name }}</strong></el-tooltip><small>素材 ID：{{ row.id }}</small><span v-if="row.aigc" class="ai-tag">AIGC</span><el-tooltip v-if="row.reasons.length" :content="row.reasons.join('；')"><span class="material-status" :class="{ deleted: row.deleted }">{{ stateText(row) }}<template v-if="row.auditStatus"> · {{ auditText(row.auditStatus) }}</template></span></el-tooltip><span v-else class="material-status" :class="{ deleted: row.deleted }">{{ stateText(row) }}<template v-if="row.auditStatus"> · {{ auditText(row.auditStatus) }}</template></span></div></div></template></el-table-column>
      <el-table-column label="操作" width="80"><template #default="{ row }"><el-button link type="primary" aria-label="查看素材" :disabled="!canPreview(row)" @click="preview = row">预览</el-button></template></el-table-column>
      <el-table-column label="商品信息" min-width="190"><template #default="{ row }"><div v-for="p in row.products" :key="p.id" class="material-product"><img v-if="p.imageUrl" :src="p.imageUrl" alt="关联商品" /><div><el-tooltip :content="p.name"><strong>{{ p.name }}</strong></el-tooltip><small>ID：{{ p.id }}</small></div></div><span v-if="!row.products.length" class="muted">—</span></template></el-table-column>
      <el-table-column label="标签" width="100"><template #default="{ row }"><div class="material-tags"><el-tag v-for="t in row.tags" :key="t" size="small" :type="t === 'FIRST_PUBLISH_MATERIAL' ? 'success' : 'info'">{{ tagText(t) }}</el-tag><span v-if="!row.tags.length">—</span></div></template></el-table-column>
      <el-table-column label="创建时间" prop="createTime" sortable="custom" width="130"><template #default="{ row }"><span class="material-time">{{ timeText(row.createTime) }}</span></template></el-table-column>
      <el-table-column v-for="m in columns" :key="m.key" :prop="`metrics.${m.key}`" :label="m.label" :min-width="m.width" sortable="custom" align="right"><template #default="{ row }">{{ value(row.metrics[m.key], m.kind) }}</template></el-table-column>
    </el-table>
    <div v-if="filtered.length" class="material-summary"><span>共 {{ filtered.length }} 个{{ categoryLabel }}<span v-if="selected.length"> · 已选择 {{ selected.length }} 个</span></span><div v-for="m in columns.filter(c => summary[c.key] != null)" :key="m.key"><small>{{ m.label }}</small><strong>{{ value(summary[m.key], m.kind) }}</strong></div></div>
    <footer class="material-footer"><span>区间：{{ range[0] }} ～ {{ range[1] }} · 当前计划<br />指标按每条素材统计；未返回的字段显示「—」。创建时间为千川返回的素材时间。</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="filtered.length" :page-sizes="[10, 20, 50, 100]" layout="total, prev, pager, next, sizes" @size-change="page = 1" /></footer>
    <el-dialog :model-value="!!preview" :title="preview?.name || '素材预览'" width="min(600px, calc(100vw - 32px))" append-to-body destroy-on-close @close="preview = undefined">
      <div class="material-preview-dialog"><MaterialPreview v-if="preview && ['VIDEO', 'IMAGE', 'CAROUSEL'].includes(preview.type)" :key="preview.id" :material="previewMaterial" :product="previewProduct" :account="account" /><blockquote v-else-if="preview?.type === 'TITLE'">{{ preview.text || preview.name }}</blockquote><img v-else-if="preview?.posterUrl" :src="preview.posterUrl" alt="其他素材预览" /></div><p class="preview-detail">素材 ID：{{ preview?.id }}</p>
    </el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { Download, Filter, Search, Setting, VideoPlay } from '@element-plus/icons-vue';
import type { TableInstance } from 'element-plus';
import { insightMaterials, type MaterialMetrics, type PlanMaterial, type PlanMaterials } from '@/features/delivery/planInsightsApi';
import type { StatisticsRange } from '@/features/delivery/statisticsRange';
import type { CreationMaterial, CreationProduct } from '@/features/delivery/creationApi';
import MaterialPreview from '../create/MaterialPreview.vue';
const props = defineProps<{ planId: string; range: StatisticsRange; refreshToken: number; account?: { awemeName: string; avatar?: string } }>();
const types = [{ id: 'VIDEO', label: '视频' }, { id: 'AIGC', label: 'AIGC' }, { id: 'IMAGE', label: '图片' }, { id: 'CAROUSEL', label: '图文' }, { id: 'OTHER', label: '其他素材' }, { id: 'TITLE', label: '标题' }];
const type = ref('VIDEO'), data = ref<PlanMaterials>(), loading = ref(false), error = ref(''), searchDraft = ref(''), keyword = ref(''), product = ref(''), status = ref(''), tag = ref('');
const table = ref<TableInstance>(), selected = ref<PlanMaterial[]>([]), preview = ref<PlanMaterial>(), page = ref(1), pageSize = ref(10), sort = ref({ key: 'metrics.shows', order: 'descending' });
const categoryLabel = computed(() => types.find(t => t.id === type.value)!.label), filterCount = computed(() => [status.value, product.value, tag.value].filter(Boolean).length);
const states: Record<string, string> = { DELIVERY_OK: '投放中', DELIVERY_NOT: '不可投放', EXCLUDE: '已排除', DELETED: '已删除' };
const tagNames: Record<string, string> = { FIRST_PUBLISH_MATERIAL: '首发', HIGH_QUALITY_MATERIAL: '优质素材', LOW_QUALITY_MATERIAL: '低质素材', INEFFICIENT_MATERIAL: '低效素材', CARRY_MATERIAL: '搬运素材', SIMILAR_MATERIAL: '相似素材' };
const tagText = (t: string) => tagNames[t] || t, typeText = (t: string) => types.find(v => v.id === t)?.label || '其他素材';
const stateText = (m: PlanMaterial) => m.deleted ? '已删除' : states[m.status || ''] || m.status || '状态未返回';
const auditText = (s?: string) => ({ PASS: '审核通过', AUDIT_PASS: '审核通过', REJECT: '审核拒绝', AUDIT_REJECT: '审核拒绝', AUDITING: '审核中', AUDIT_ING: '审核中' } as Record<string, string>)[s || ''] || s || '—';
const goods = computed(() => [...new Map((data.value?.records || []).flatMap(r => r.products).map(p => [p.id, p])).values()]);
const tags = computed(() => [...new Set((data.value?.records || []).flatMap(r => r.tags))]);
const metrics: { key: keyof MaterialMetrics; label: string; kind: string; width: number }[] = [
  { key: 'shows', label: '整体展示次数', kind: 'count', width: 130 }, { key: 'clicks', label: '整体点击次数', kind: 'count', width: 130 }, { key: 'ctr', label: '整体点击率', kind: 'rate', width: 115 }, { key: 'cvr', label: '整体转化率', kind: 'rate', width: 115 },
  { key: 'cost', label: '整体消耗（元）', kind: 'number', width: 140 }, { key: 'orders', label: '整体成交订单数', kind: 'count', width: 155 }, { key: 'gmv', label: '整体成交金额（元）', kind: 'number', width: 175 }, { key: 'roi', label: '整体支付 ROI', kind: 'number', width: 140 },
  { key: 'orderCost', label: '整体成交订单成本', kind: 'number', width: 165 }, { key: 'netRoi', label: '净成交 ROI', kind: 'number', width: 125 }, { key: 'netGmv', label: '净成交金额（元）', kind: 'number', width: 155 }, { key: 'settlementRate', label: '净成交金额结算率', kind: 'rate', width: 165 }, { key: 'refundRate', label: '1小时内退款率', kind: 'rate', width: 150 },
];
const visibleColumns = ref(metrics.map(m => m.key)), columns = computed(() => metrics.filter(m => visibleColumns.value.includes(m.key)));
const filtered = computed(() => {
  const text = keyword.value.toLocaleLowerCase();
  const rows = (data.value?.records || []).filter(r => (!text || r.name.toLocaleLowerCase().includes(text) || r.id.includes(text)) && (!product.value || r.products.some(p => p.id === product.value)) && (!tag.value || r.tags.includes(tag.value)) && (!status.value || (status.value === 'DELETED' ? r.deleted || r.status === 'DELETED' : !r.deleted && r.status === status.value)));
  if (!sort.value.order) return rows;
  const factor = sort.value.order === 'ascending' ? 1 : -1, key = sort.value.key;
  return [...rows].sort((a, b) => { const x = key === 'createTime' ? a.createTime : a.metrics[key.replace('metrics.', '') as keyof MaterialMetrics], y = key === 'createTime' ? b.createTime : b.metrics[key.replace('metrics.', '') as keyof MaterialMetrics]; if (x == null) return y == null ? 0 : 1; if (y == null) return -1; return (typeof x === 'string' ? x.localeCompare(String(y)) : Number(x) - Number(y)) * factor; });
});
const filteredEmpty = computed(() => filterCount.value || keyword.value ? '没有符合筛选条件的素材' : `千川未返回当前计划的${categoryLabel.value}素材`);
const paged = computed(() => filtered.value.slice((page.value - 1) * pageSize.value, page.value * pageSize.value));
const summary = computed<MaterialMetrics>(() => {
  const result: MaterialMetrics = {};
  for (const key of ['shows', 'clicks', 'cost', 'orders', 'gmv', 'netGmv'] as const) { const values = filtered.value.map(r => r.metrics[key]); result[key] = values.length && values.every(v => v != null) ? values.reduce<number>((sum, v) => sum + Number(v), 0) : null; }
  const ratio = (a: number | null | undefined, b: number | null | undefined, f: number) => a == null || b == null ? null : b ? a / b * f : a === 0 ? 0 : null;
  result.ctr = ratio(result.clicks, result.shows, 100); result.cvr = ratio(result.orders, result.clicks, 100); result.roi = ratio(result.gmv, result.cost, 1); result.orderCost = ratio(result.cost, result.orders, 1); result.netRoi = ratio(result.netGmv, result.cost, 1);
  return result;
});
function value(v: number | null | undefined, kind: string) { return v == null ? '—' : kind === 'count' ? Number(v).toLocaleString('zh-CN') : `${Number(v).toFixed(2)}${kind === 'rate' ? '%' : ''}`; }
function timeText(v?: string) { if (!v) return '—'; return /Z$|[+-]\d\d:\d\d$/.test(v) ? new Date(v).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) : v.replace('T', ' '); }
function search() { keyword.value = searchDraft.value.trim(); }
function clearFilters() { product.value = status.value = tag.value = keyword.value = searchDraft.value = ''; }
function sortChange(e: { prop: string; order: string }) { sort.value = { key: e.prop, order: e.order }; }
const safeUrl = (v?: string) => !!v && /^https?:\/\//i.test(v);
function canPreview(row: PlanMaterial) { return row.type === 'TITLE' || safeUrl(row.previewUrl) || safeUrl(row.posterUrl) || row.imageUrls.some(safeUrl); }
const previewMaterial = computed<CreationMaterial | undefined>(() => preview.value ? { id: preview.value.id, productId: preview.value.products[0]?.id || '', type: preview.value.type as CreationMaterial['type'], title: preview.value.name, text: preview.value.text, status: 'READY', previewUrl: preview.value.type === 'CAROUSEL' ? preview.value.musicUrl : preview.value.previewUrl, posterUrl: preview.value.posterUrl, imageUrls: preview.value.imageUrls, titles: [] } : undefined);
const previewProduct = computed<CreationProduct | undefined>(() => { const p = preview.value?.products[0]; return p ? { productId: p.id, qcProductId: p.id, name: p.name, imageUrl: p.imageUrl, price: null, userPrice: null, tags: [], unavailableReasons: [] } : undefined; });
function download() {
  const cell = (v: unknown) => `"${String(v ?? '').replace(/"/g, '""')}"`, textCell = (v: string) => cell(`\t${v}`);
  const headers = ['素材名称', '素材ID', '类型', '对应商品', '商品ID', '标签', '创建时间', '投放状态', ...columns.value.map(c => c.label)];
  const rows = filtered.value.map(r => [textCell(r.name), textCell(r.id), cell(typeText(r.type)), textCell(r.products.map(p => p.name).join('；')), textCell(r.products.map(p => p.id).join('；')), cell(r.tags.map(tagText).join('；')), cell(timeText(r.createTime)), cell(stateText(r)), ...columns.value.map(c => cell(value(r.metrics[c.key], c.kind)))].join(','));
  const url = URL.createObjectURL(new Blob(['\uFEFF' + [headers.map(cell).join(','), ...rows].join('\r\n')], { type: 'text/csv;charset=utf-8;' })); const link = document.createElement('a'); link.href = url; link.download = `计划素材_${props.planId}_${type.value}_${props.range.join('_')}.csv`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
let request = 0, disposed = false;
async function load() { const turn = ++request; loading.value = true; error.value = ''; data.value = undefined; preview.value = undefined; selected.value = []; table.value?.clearSelection(); page.value = 1; try { const result = await insightMaterials(props.planId, props.range, type.value); if (!disposed && turn === request) data.value = result; } catch (e: any) { if (!disposed && turn === request) error.value = e?.message || e?.response?.data?.message || '素材查询失败，请稍后重试'; } finally { if (!disposed && turn === request) loading.value = false; } }
watch(() => [props.planId, props.range[0], props.range[1], props.refreshToken, type.value], () => { clearFilters(); void load(); });
watch([keyword, product, status, tag], () => { page.value = 1; selected.value = []; table.value?.clearSelection(); });
onMounted(load); onBeforeUnmount(() => { disposed = true; request++; });
</script>
<style scoped>
