9297a9}.material-summary{display:flex;align-items:center;flex-wrap:wrap;gap:14px 22px;background:#fafbff;border-bottom:1px solid #eaecf4;padding:14px;font-size:12px}.material-summary>span{color:#70758c}.material-summary small{display:block;color:#8b90a5;margin-bottom:5px;font-size:11px}.material-summary strong{font-size:13px}.material-footer{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-top:19px;color:#9398ac;font-size:11px;line-height:1.8}.material-footer :deep(.el-pagination){flex-wrap:wrap;row-gap:8px;max-width:100%;margin:0}.material-preview-dialog{display:flex;justify-content:center}.material-preview-dialog :deep(.preview){margin:0;width:340px;max-width:100%;box-sizing:border-box}.material-preview-dialog>img{max-width:100%;max-height:70vh}.material-preview-dialog blockquote{font-size:18px;line-height:1.8;overflow-wrap:anywhere}.preview-detail{font-size:12px;color:#8b90a5}.plan-materials>.el-alert{margin-bottom:14px}.plan-materials :deep(.el-table){font-size:12px}.plan-materials :deep(.el-table__header th){background:#f7f8fc}.plan-materials :deep(.el-checkbox-group){display:flex;flex-direction:column}
@media(max-width:700px){.material-categories button{padding:8px 17px}.material-toolbar>.el-input{width:100%}.material-footer{align-items:flex-start;flex-direction:column}.material-summary{gap:12px 16px}}
</style>
